package it.comune.trieste.ouf.udp;

import static org.assertj.core.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;

@SpringBootTest
class LinkedPropertyRuntimeTest {
  @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->required("OUF_UDP_DB_URL"));r.add("spring.datasource.username",()->required("OUF_UDP_DB_USER"));r.add("spring.datasource.password",()->required("OUF_UDP_DB_PASSWORD"));}
  @Autowired HandoffIntakeService intake;@Autowired ObjectResolutionService resolution;@Autowired CanonicalMaterializer materializer;@Autowired JdbcClient db;@Autowired PropertyGovernanceService governance;@Autowired com.fasterxml.jackson.databind.ObjectMapper json;
  final UdpPorts.ResolutionProfile identity=new UdpPorts.ResolutionProfile("CANONICAL_KEY","1","policy://resolution/1","ouf:Asset","code","code");
  @Autowired GovernedServingService serving;
  @Test void xsdStringProfileSurvivesPinningPreviewAndMaterialization() throws Exception {
    var rule=new UdpPorts.PropertyRule("name","name","http://www.w3.org/2001/XMLSchema#string","OPEN",List.of(),new LinkedPropertyReconciler.Rule(LinkedPropertyReconciler.POLICY,"SINGLE","EXACT_TYPED",1,"SOURCE_INTERVAL",null,null));
    var p=profile(rule);UUID object=accept(handoff("xsd-a","api","a",Map.of("name","Name")),p);
    var incoming=handoff("xsd-b","file","b",Map.of("name","Name"));intake.accept(incoming);
    LinkedPropertyPreview.remember(db,"xsd-b","ouf:Asset","bundle://asset/1",p);
    var preview=LinkedPropertyPreview.prepare(db,json,"xsd-b",object.toString(),"default");
    assertThat(preview.get("available")).isEqualTo(true);
    assertThat(json.writeValueAsString(preview)).contains("Name");
    materializer.materialize("xsd-b",object,incoming,p);
    assertThat(current()).contains("Name");assertThat(count("property_contribution")).isEqualTo(2);
    assertThat(count("property_conflict")).isZero();
    assertThat(db.sql("select reconciliation_evidence::text from ouf_udp.property_value where revision_id=(select current_revision_id from ouf_udp.urban_object)").query(String.class).single()).contains("lineage-xsd-a","lineage-xsd-b","http://www.w3.org/2001/XMLSchema#string");
  }
  @Test void unionCannotExposeRestrictedMemberThroughAnOpenRepresentative(){
    var open=rule("phone","MULTI");var restricted=new UdpPorts.PropertyRule(open.sourceField(),open.propertyIri(),open.datatype(),"RESTRICTED",open.authorityOrder(),open.reconciliation());
    UUID object=accept(handoff("a","restricted-api","a",Map.of("phone","private")),profile(restricted));
    accept(handoff("b","public-layer","b",Map.of("phone","public")),profile(open));
    var caps=Set.of("urban.object.read");
    var publicReader=new ServingAuthorizationContext("HUMAN","reader","default",caps,Set.of("OPEN"),"auth","c");
    var fullReader=new ServingAuthorizationContext("HUMAN","reader","default",caps,Set.of("OPEN","RESTRICTED"),"auth","c");
    assertThat(((Map<?,?>)serving.current(object,publicReader).get("properties")).containsKey("phone")).isFalse();
    assertThat(String.valueOf(serving.current(object,fullReader).get("properties"))).contains("private","public");
  }
  @Test @SuppressWarnings("unchecked") void temporalIntervalComesFromWinningValueNotLastIncomingSource(){
    var r=new UdpPorts.PropertyRule("name","name","string","OPEN",List.of("registry","survey"),new LinkedPropertyReconciler.Rule(LinkedPropertyReconciler.POLICY,"SINGLE","EXACT_TYPED",1,"SOURCE_INTERVAL",null,null));
    var p=new UdpPorts.MaterializationProfile(LinkedPropertyReconciler.POLICY,List.of(r),Set.of("name"),1);
    var a=handoff("a","registry","a",Map.of("name","official"));((Map<String,Object>)a.get("sourceIdentity")).put("validFrom","2020-01-01T00:00:00Z");accept(a,p);
    var b=handoff("b","survey","b",Map.of("name","other"));((Map<String,Object>)b.get("sourceIdentity")).put("validFrom","2021-01-01T00:00:00Z");accept(b,p);
    assertThat(current()).contains("official");
    assertThat(db.sql("select valid_from from ouf_udp.property_bitemporal_interval where system_to is null").query(java.time.OffsetDateTime.class).single()).isEqualTo(java.time.OffsetDateTime.parse("2020-01-01T00:00:00Z"));
  }
  @BeforeEach void clean(){db.sql("truncate table ouf_udp.urban_object,ouf_udp.handoff_intake restart identity cascade").update();}
  UdpPorts.PropertyRule rule(String field,String cardinality){return new UdpPorts.PropertyRule(field,field,"string","OPEN",List.of(),new LinkedPropertyReconciler.Rule(LinkedPropertyReconciler.POLICY,cardinality,"NFC_TRIM",1,"SOURCE_INTERVAL",null,null));}
  UdpPorts.MaterializationProfile profile(UdpPorts.PropertyRule... rules){return new UdpPorts.MaterializationProfile(LinkedPropertyReconciler.POLICY,List.of(rules));}
  Map<String,Object> handoff(String id,String source,String record,Map<String,Object> fields){var payload=new LinkedHashMap<String,Object>(fields);payload.put("code","SHARED-IDENTITY");return new LinkedHashMap<>(Map.ofEntries(Map.entry("handoffId",id),Map.entry("ingestionRunId","run-1"),Map.entry("ingestionId","ing-"+id),Map.entry("sourceIdentity",new LinkedHashMap<>(Map.of("sourceId",source,"typeCode","ASSET","sourceObjectId",record,"observedAt","2026-09-12T00:00:00Z"))),Map.entry("operation","UPSERT"),Map.entry("canonicalPayload",payload),Map.entry("rawObjectRef","raw://"+id),Map.entry("contractRefs",Map.of("sourceSchemaRef","schema://asset/1","bundleRef","bundle://asset/1","semanticPublicationSetRef","semantic://publication/1","adapterProfileRef","adapter://api/1")),Map.entry("lineageId","lineage-"+id),Map.entry("contentHash","sha256:"+id),Map.entry("acquiredAt","2026-09-12T00:00:00Z"),Map.entry("changeRepresentation",Map.of("mode","FULL_SNAPSHOT"))));}
  UUID accept(Map<String,Object> h,UdpPorts.MaterializationProfile p){String id=h.get("handoffId").toString();intake.accept(h);var decision=resolution.resolve(id,h,identity);LinkedPropertyPreview.remember(db,id,"ouf:Asset","bundle://asset/1",p);materializer.materialize(id,decision.targetUrbanObjectId(),h,p);return decision.targetUrbanObjectId();}
  String current(){return db.sql("select canonical_payload::text from ouf_udp.urban_object_current_state").query(String.class).single();}
  long count(String table){return db.sql("select count(*) from ouf_udp."+table).query(Long.class).single();}
  @Test void complementaryApiAndFileRecordsPreserveFieldsAndLineage(){var p=profile(rule("name","SINGLE"),rule("phone","SINGLE"));var a=handoff("a","registry-api","record-a",Map.of("name","Asset A"));UUID object=accept(a,p);var b=handoff("b","geopackage","feature-b",Map.of("phone","123"));assertThat(accept(b,p)).isEqualTo(object);assertThat(current()).contains("Asset A","123");assertThat(count("urban_object")).isOne();assertThat(count("property_contribution")).isEqualTo(2);assertThat(materializer.materialize("b",object,b,p).duplicate()).isTrue();assertThat(count("property_contribution")).isEqualTo(2);}
  @Test void deltaOmissionsNullAndBlankDoNotEraseExistingValues(){var p=profile(rule("name","SINGLE"),rule("phone","SINGLE"));UUID object=accept(handoff("a","api","a",Map.of("name","Keep","phone","123")),p);var fields=new LinkedHashMap<String,Object>();fields.put("name",null);fields.put("phone","  ");var b=handoff("b","api","a",fields);b.put("changeRepresentation",Map.of("mode","DELTA_PATCH","baseRevisionRef",db.sql("select current_revision_id::text from ouf_udp.urban_object").query(String.class).single()));accept(b,p);assertThat(current()).contains("Keep","123");assertThat(count("property_contribution")).isEqualTo(2);}
  @Test void normalizedValuesHaveAllOriginalContributionsAndMaterializedMembers(){var p=profile(rule("name","SINGLE"));accept(handoff("a","api","a",Map.of("name"," Cafe\u0301 ")),p);accept(handoff("b","file","b",Map.of("name","Café")),p);assertThat(current()).contains("Café");String evidence=db.sql("select reconciliation_evidence::text from ouf_udp.property_value where revision_id=(select current_revision_id from ouf_udp.urban_object)").query(String.class).single();assertThat(evidence).contains("lineage-a","lineage-b","originalValue","normalizedValue");assertThat(count("property_conflict")).isZero();}
  @Test void sameSourceDistinctRowsConflictOnlyOnOneProperty(){var p=profile(rule("name","SINGLE"),rule("phone","SINGLE"));accept(handoff("a","layer","feature-a",Map.of("name","A")),p);accept(handoff("b","layer","feature-b",Map.of("name","B","phone","123")),p);assertThat(current()).contains("A","123").doesNotContain("\"B\"");assertThat(count("property_conflict")).isOne();assertThat(db.sql("select authority_state->'name'->>'status' from ouf_udp.urban_object_current_state").query(String.class).single()).isEqualTo("CONFLICT");assertThat(count("property_contribution")).isEqualTo(3);}
  @Test void unionRetainsEveryMemberProvenance(){var p=profile(rule("phone","MULTI"));accept(handoff("a","api","a",Map.of("phone",List.of("111","222"))),p);accept(handoff("b","layer","b",Map.of("phone",List.of("222","333"))),p);assertThat(current()).contains("111","222","333");String evidence=db.sql("select reconciliation_evidence::text from ouf_udp.property_value where revision_id=(select current_revision_id from ouf_udp.urban_object)").query(String.class).single();var e=json.valueToTree(LinkedPropertyReconciler.decode(evidence));assertThat(e.path("members").size()).isEqualTo(3);assertThat(e.path("members").findValuesAsText("sourceId")).contains("api","layer");}
  @Test void sourceRevisionAndExplicitDeletePreserveHistory(){var r=new UdpPorts.PropertyRule("name","name","string","OPEN",List.of("api"),new LinkedPropertyReconciler.Rule(LinkedPropertyReconciler.POLICY,"SINGLE","EXACT_TYPED",1,"SOURCE_INTERVAL","revision","deleteName"));var p=profile(r);accept(handoff("a","api","a",Map.of("name","old","revision",1)),p);accept(handoff("b","api","a",Map.of("revision",2,"deleteName",true)),p);assertThat(current()).doesNotContain("old");assertThat(count("property_contribution")).isEqualTo(2);assertThat(db.sql("select count(*) from ouf_udp.property_value where revision_id=(select current_revision_id from ouf_udp.urban_object)").query(Long.class).single()).isZero();assertThat(count("object_revision")).isEqualTo(2);}
  @Test void previewUsesPinnedProfileAndSameReconcilerWithTenantIsolation(){var p=profile(rule("name","SINGLE"),rule("phone","SINGLE"));UUID object=accept(handoff("a","api","a",Map.of("name","A")),p);var b=handoff("b","file","b",Map.of("name","B","phone","123"));intake.accept(b);LinkedPropertyPreview.remember(db,"b","ouf:Asset","bundle://asset/1",p);var preview=LinkedPropertyPreview.prepare(db,json,"b",object.toString(),"default");assertThat(preview.get("available")).isEqualTo(true);var props=(Map<?,?>)preview.get("properties");assertThat(((Map<?,?>)props.get("name")).get("status")).isEqualTo("CONFLICT");assertThat(((Map<?,?>)props.get("phone")).get("proposedValue")).isEqualTo("123");assertThat(count("property_contribution")).isOne();assertThat(LinkedPropertyPreview.prepare(db,json,"b",object.toString(),"foreign").get("available")).isEqualTo(false);assertThatThrownBy(()->LinkedPropertyPreview.remember(db,"b","ouf:Asset","bundle://other/1",p)).hasMessageContaining("UDP_PROPERTY_PROFILE_DRIFT");}
  @Test void staleHumanPropertyChoiceDoesNotOverrideNewEvidence(){var p=profile(rule("name","SINGLE"));accept(handoff("a","api","a",Map.of("name","A")),p);accept(handoff("b","file","b",Map.of("name","B")),p);UUID conflict=db.sql("select conflict_id from ouf_udp.property_conflict").query(UUID.class).single();UUID revision=db.sql("select current_revision_id from ouf_udp.urban_object").query(UUID.class).single();UUID chosen=db.sql("select contribution_id from ouf_udp.property_contribution where handoff_id='b'").query(UUID.class).single();accept(handoff("c","third-api","c",Map.of("name","C")),p);var caps=Set.of("authority.override","resolution.issue.read","urban.object.read");var actor=new TrustedHumanContext("HUMAN","operator","default",caps,"auth","c");var auth=new ServingAuthorizationContext("HUMAN","operator","default",caps,Set.of("OPEN"),"auth","c");assertThatThrownBy(()->governance.decide(conflict,revision,chosen,"verified",actor,auth)).hasMessageContaining("409");assertThat(count("human_property_decision")).isZero();}
  @Test void correctHumanChoiceOnlyChangesItsPropertyAndKeepsProvenance(){var p=profile(rule("name","SINGLE"),rule("phone","SINGLE"));accept(handoff("a","api","a",Map.of("name","A","phone","123")),p);accept(handoff("b","file","b",Map.of("name","B")),p);UUID conflict=db.sql("select conflict_id from ouf_udp.property_conflict").query(UUID.class).single();UUID revision=db.sql("select current_revision_id from ouf_udp.urban_object").query(UUID.class).single();UUID chosen=db.sql("select contribution_id from ouf_udp.property_contribution where handoff_id='b'").query(UUID.class).single();var caps=Set.of("authority.override","resolution.issue.read","urban.object.read");var actor=new TrustedHumanContext("HUMAN","operator","default",caps,"auth","c");var auth=new ServingAuthorizationContext("HUMAN","operator","default",caps,Set.of("OPEN"),"auth","c");assertThat(governance.review(conflict,auth)).containsEntry("currentValue","A");governance.decide(conflict,revision,chosen,"verified",actor,auth);assertThat(current()).contains("B","123");assertThat(count("human_property_decision")).isOne();}
  private static String required(String key){return Objects.requireNonNull(System.getenv(key),key+" required");}
}
